files.content:
* {
  box-sizing: border-box;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #80d994;
}

h1,
h2,
h3,
h4,
h5,
h6,
p {
  margin: 0;
}

.card {
  display: grid;
  grid-template-columns: 200px auto 1fr;
  gap: 20px;
  width: 800px;
}

.card__title {
  font-weight: 800;
  font-size: 28px;
  line-height: 0.85;
  text-transform: uppercase;
}

.card__image {
  grid-row: 1/3;



  width: 100%;
  border: 1px solid #000;
}

.card__text {
  grid-column: 2/-1;
}

.card__button {
  display: flex;
  justify-content: center;
  align-items: center;



  gap: 8px;
  width: 200px;
  height: 50px;
  border: 1px solid #fff;
  border-radius: 40px;
  color: #fff;
  font-weight: 800;
  font-size: 14px;
  text-transform: uppercase;
  background-color: #000;
  justify-self: end;
}

.card__button img {
  width: 20px;
}
